mkuse!{use derive_where :: derive_where ;}
mkuse!{use rustc_type_ir_macros :: { TypeFoldable_Generic , TypeVisitable_Generic } ;}
mkuse!{use crate :: solve :: { CandidateSource , Certainty , Goal , GoalSource , QueryResult } ;}
mkuse!{use crate :: { Canonical , CanonicalVarValues , Interner } ;}
mkitem!{mkstruct!{# [doc = " Some `data` together with information about how they relate to the input"] # [doc = " of the canonical query."] # [doc = ""] # [doc = " This is only ever used as [CanonicalState]. Any type information in proof"] # [doc = " trees used mechanically has to be canonicalized as we otherwise leak"] # [doc = " inference variables from a nested `InferCtxt`."] # [derive_where (Clone , PartialEq , Hash , Debug ; I : Interner , T)] # [derive_where (Copy ; I : Interner , T : Copy)] # [derive (TypeVisitable_Generic , TypeFoldable_Generic)] pub struct State < I : Interner , T > { pub var_values : CanonicalVarValues < I > , pub data : T , }}}
mkitem!{mkimpl!{impl < I : Interner , T : Eq > Eq for State < I , T > { }}}
mkitem!{pub type CanonicalState < I , T > = Canonical < I , State < I , T > > ;}
mkitem!{mkstruct!{# [doc = " When evaluating a goal we also store the original values"] # [doc = " for the `CanonicalVarValues` of the canonicalized goal."] # [doc = " We use this to map any [CanonicalState] from the local `InferCtxt`"] # [doc = " of the solver query to the `InferCtxt` of the caller."] # [derive_where (PartialEq , Eq , Hash ; I : Interner)] pub struct GoalEvaluation < I : Interner > { pub uncanonicalized_goal : Goal < I , I :: Predicate > , pub orig_values : Vec < I :: GenericArg > , pub final_revision : I :: Probe , pub result : QueryResult < I > , }}}
mkitem!{mkstruct!{# [doc = " A self-contained computation during trait solving. This either"] # [doc = " corresponds to a `EvalCtxt::probe(_X)` call or the root evaluation"] # [doc = " of a goal."] # [derive_where (PartialEq , Eq , Hash , Debug ; I : Interner)] pub struct Probe < I : Interner > { # [doc = " What happened inside of this probe in chronological order."] pub steps : Vec < ProbeStep < I > > , pub kind : ProbeKind < I > , pub final_state : CanonicalState < I , () > , }}}
mkitem!{mkenum!{# [derive_where (PartialEq , Eq , Hash , Debug ; I : Interner)] pub enum ProbeStep < I : Interner > { # [doc = " We added a goal to the `EvalCtxt` which will get proven"] # [doc = " the next time `EvalCtxt::try_evaluate_added_goals` is called."] AddGoal (GoalSource , CanonicalState < I , Goal < I , I :: Predicate > >) , # [doc = " A call to `probe` while proving the current goal. This is"] # [doc = " used whenever there are multiple candidates to prove the"] # [doc = " current goal."] NestedProbe (Probe < I >) , # [doc = " A trait goal was satisfied by an impl candidate."] RecordImplArgs { impl_args : CanonicalState < I , I :: GenericArgs > } , # [doc = " A call to `EvalCtxt::evaluate_added_goals_make_canonical_response` with"] # [doc = " `Certainty` was made. This is the certainty passed in, so it's not unified"] # [doc = " with the certainty of the `try_evaluate_added_goals` that is done within;"] # [doc = " if it's `Certainty::Yes`, then we can trust that the candidate is \"finished\""] # [doc = " and we didn't force ambiguity for some reason."] MakeCanonicalResponse { shallow_certainty : Certainty } , }}}
mkitem!{mkenum!{# [doc = " What kind of probe we're in. In case the probe represents a candidate, or"] # [doc = " the final result of the current goal - via [ProbeKind::Root] - we also"] # [doc = " store the [QueryResult]."] # [derive_where (Clone , Copy , PartialEq , Eq , Hash , Debug ; I : Interner)] # [derive (TypeVisitable_Generic , TypeFoldable_Generic)] pub enum ProbeKind < I : Interner > { # [doc = " The root inference context while proving a goal."] Root { result : QueryResult < I > } , # [doc = " Probe entered when normalizing the self ty during candidate assembly"] NormalizedSelfTyAssembly , # [doc = " A candidate for proving a trait or alias-relate goal."] TraitCandidate { source : CandidateSource < I > , result : QueryResult < I > } , # [doc = " Used in the probe that wraps normalizing the non-self type for the unsize"] # [doc = " trait, which is also structurally matched on."] UnsizeAssembly , # [doc = " Used to do a probe to find out what projection type(s) match a given"] # [doc = " alias bound or projection predicate. For trait upcasting, this is used"] # [doc = " to prove that the source type upholds all of the target type's object"] # [doc = " bounds. For object type bounds, this is used when eagerly replacing"] # [doc = " supertrait aliases."] ProjectionCompatibility , # [doc = " Looking for param-env candidates that satisfy the trait ref for a projection."] ShadowedEnvProbing , # [doc = " Try to unify an opaque type with an existing key in the storage."] OpaqueTypeStorageLookup { result : QueryResult < I > } , # [doc = " Checking that a rigid alias is well-formed."] RigidAlias { result : QueryResult < I > } , }}}